import pulp

# Define parameters from the problem
num_phases = 7
num_tasks_per_phase = 7
num_teams = 7

duration = [
    [5, 3, 6, 2, 3, 1, 3],
    [2, 8, 9, 6, 6, 2, 1],
    [8, 6, 9, 6, 2, 2, 5],
    [5, 4, 8, 6, 5, 7, 10],
    [6, 6, 7, 5, 6, 7, 5],
    [6, 4, 3, 6, 8, 4, 2],
    [7, 9, 5, 8, 4, 6, 9]
]

team_assignment = [
    [4, 5, 1, 3, 2, 6, 7],
    [5, 7, 2, 1, 4, 6, 3],
    [2, 7, 4, 3, 6, 1, 5],
    [5, 4, 2, 3, 7, 1, 6],
    [2, 1, 4, 3, 5, 7, 6],
    [7, 1, 4, 3, 6, 2, 5],
    [6, 4, 7, 5, 3, 2, 1]
]

# Create the model
model = pulp.LpProblem("Construction_Project_Scheduling", pulp.LpMinimize)

# Decision variables
# start_time[phase][task]
start_time = {}
for p in range(num_phases):
    for t in range(num_tasks_per_phase):
        start_time[p][t] = pulp.LpVariable(f"start_time_{p}_{t}", lowBound=0)

# end_time[phase][task]
end_time = {}
for p in range(num_phases):
    for t in range(num_tasks_per_phase):
        end_time[p][t] = pulp.LpVariable(f"end_time_{p}_{t}", lowBound=0)

# assign_team[team][phase][task] - binary variable indicating if team is assigned to this task
# Note: This is redundant since team_assignment is fixed, but we'll use it for constraints
assign_team = {}
for team in range(1, num_teams + 1):
    assign_team[team] = {}
    for p in range(num_phases):
        assign_team[team][p] = {}
        for t in range(num_tasks_per_phase):
            assign_team[team][p][t] = pulp.LpVariable(f"assign_team_{team}_{p}_{t}", cat='Binary')

# precedence_order[task1][task2] - binary variable indicating task1 completes before task2 starts (on same team)
# We'll define this for pairs of tasks that might conflict on the same team
# We'll create a dictionary for all pairs of tasks that are assigned to the same team
precedence_order = {}
for team in range(1, num_teams + 1):
    precedence_order[team] = {}
    # Find all tasks assigned to this team
    tasks_on_team = []
    for p in range(num_phases):
        for t in range(num_tasks_per_phase):
            if team_assignment[p][t] == team:
                tasks_on_team.append((p, t))
    # Create precedence variables for every pair of distinct tasks on this team
    for i, task1 in enumerate(tasks_on_team):
        for j, task2 in enumerate(tasks_on_team):
            if i != j:
                precedence_order[team][f"{task1}_{task2}"] = pulp.LpVariable(
                    f"precedence_order_{team}_{task1[0]}_{task1[1]}_{task2[0]}_{task2[1]}", cat='Binary'
                )

# Makespan variable (to be minimized)
makespan = pulp.LpVariable("makespan", lowBound=0)

# Objective: minimize makespan
model += makespan, "Objective"

# R1: Each task in a phase must start only after the previous task in the same phase has finished.
# R3: The start time of a task must be greater than or equal to the end time of its predecessor in the same phase.
# Note: R1 and R3 are essentially the same. We'll implement R3 as the constraint.
for p in range(num_phases):
    for t in range(1, num_tasks_per_phase):  # t from 1 to 6 (0-indexed)
        model += start_time[p][t] >= end_time[p][t-1], f"R3_precedence_{p}_{t}"

# Link end_time and start_time with duration
for p in range(num_phases):
    for t in range(num_tasks_per_phase):
        model += end_time[p][t] == start_time[p][t] + duration[p][t], f"R3_end_time_{p}_{t}"

# R2: Each team can work on only one task at a time.
# We'll use the assign_team variables to enforce this, but note: team_assignment is fixed.
# Since team_assignment is fixed, we know which tasks belong to which team.
# We need to ensure that for each team, the tasks assigned to it do not overlap.
# We'll use the precedence_order variables to enforce non-overlap.

# For each team, for every pair of tasks assigned to it, enforce non-overlap
for team in range(1, num_teams + 1):
    tasks_on_team = []
    for p in range(num_phases):
        for t in range(num_tasks_per_phase):
            if team_assignment[p][t] == team:
                tasks_on_team.append((p, t))

    # For every pair of distinct tasks on this team
    for i, (p1, t1) in enumerate(tasks_on_team):
        for j, (p2, t2) in enumerate(tasks_on_team):
            if i < j:  # avoid duplicate pairs and self
                # We need to enforce that either task1 finishes before task2 starts, or vice versa
                # Use big-M method with binary variable
                # Let x = precedence_order[team][f"{(p1,t1)}_{(p2,t2)}"]
                # If x=1: end_time[p1][t1] <= start_time[p2][t2]
                # If x=0: end_time[p2][t2] <= start_time[p1][t1]

                # We'll use the variable we created
                var_name = f"{(p1,t1)}_{(p2,t2)}"
                if var_name not in precedence_order[team]:
                    # This should not happen since we created all pairs
                    continue
                x = precedence_order[team][var_name]

                # Big M value - we can use a large number, e.g., sum of all durations
                M = sum(sum(d) for d in duration) + 1000

                # If x=1: end_time[p1][t1] <= start_time[p2][t2]
                model += end_time[p1][t1] <= start_time[p2][t2] + M * (1 - x), f"R2_non_overlap_{team}_{p1}_{t1}_{p2}_{t2}_1"
                # If x=0: end_time[p2][t2] <= start_time[p1][t1]
                model += end_time[p2][t2] <= start_time[p1][t1] + M * x, f"R2_non_overlap_{team}_{p1}_{t1}_{p2}_{t2}_2"

# R4: If two tasks from different phases are assigned to the same team, they must not overlap in time.
# This is already covered by R2 above, since we are enforcing non-overlap for all pairs of tasks on the same team.

# R5: The makespan is the maximum end time among all tasks across all phases.
for p in range(num_phases):
    for t in range(num_tasks_per_phase):
        model += makespan >= end_time[p][t], f"R5_makespan_{p}_{t}"

# Ensure that assign_team variables are consistent with team_assignment
# Since team_assignment is fixed, we set these binary variables to 1 for the correct team and 0 for others
for p in range(num_phases):
    for t in range(num_tasks_per_phase):
        assigned_team = team_assignment[p][t]
        for team in range(1, num_teams + 1):
            if team == assigned_team:
                model += assign_team[team][p][t] == 1, f"R_assign_team_{team}_{p}_{t}_fixed"
            else:
                model += assign_team[team][p][t] == 0, f"R_assign_team_{team}_{p}_{t}_fixed"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

