for p in plants:
    model += pulp.lpSum(x[p][d] for d in districts) <= capacity[p], f"R1_{p}_capacity"

# R2: Each district's total input must meet its demand exactly
for d in districts:
    model += pulp.lpSum(x[p][d] for p in plants) == demand[d], f"R2_{d}_demand"

# R3: Each transmission line must not exceed its capacity limit (already enforced by variable upper bounds)
# We don't need additional constraints because we set upBound=capacity_limit[p][d] when creating variables

# Solve the model
