    [8, 10, 2, 3],
    [7, 8, 1, 2]
]

# Create the model
model = pulp.LpProblem("Logistics_Scheduling", pulp.LpMinimize)

# Decision variables
# start_time[i][j]: start time of stage j of route i
start_time = {}
for i in range(num_routes):
    for j in range(num_stages_per_route):
        start_time[i, j] = pulp.LpVariable(f"start_time_{i}_{j}", lowBound=0)

# completion_time[i]: completion time of route i
completion_time = {}
for i in range(num_routes):
    completion_time[i] = pulp.LpVariable(f"completion_time_{i}", lowBound=0)

# assign[h][i][j]: binary variable indicating if stage j of route i is assigned to hub h
assign = {}
for h_idx, h in enumerate(hubs):
    assign[h_idx] = {}
    for i in range(num_routes):
        assign[h_idx][i] = {}
        for j in range(num_stages_per_route):
            assign[h_idx][i][j] = pulp.LpVariable(f"assign_{h_idx}_{i}_{j}", cat='Binary')

# order[h][i1][j1][i2][j2]: binary variable indicating if stage j1 of route i1 precedes stage j2 of route i2 at hub h
order = {}
for h_idx, h in enumerate(hubs):
    order[h_idx] = {}
    for i1 in range(num_routes):
        order[h_idx][i1] = {}
        for j1 in range(num_stages_per_route):
            order[h_idx][i1][j1] = {}
            for i2 in range(num_routes):
                order[h_idx][i1][j1][i2] = {}
                for j2 in range(num_stages_per_route):
                    if i1 == i2 and j1 == j2:
                        continue  # Skip self
                    order[h_idx][i1][j1][i2][j2] = pulp.LpVariable(f"order_{h_idx}_{i1}_{j1}_{i2}_{j2}", cat='Binary')

# Objective: minimize the maximum completion time
# We introduce a variable for the makespan (total completion time)
makespan = pulp.LpVariable("makespan", lowBound=0)
model += makespan, "Objective"

# R1: Each stage of a route must start only after the previous stage in the same route has completed.
for i in range(num_routes):
    for j in range(1, num_stages_per_route):
        model += start_time[i, j] >= start_time[i, j-1] + duration[i][j-1], f"R1_sequence_{i}_{j}"

# R2: Each hub can process only one stage at a time.
# We use the disjunctive constraint formulation with big-M
# For each hub h, for every pair of stages (i1,j1) and (i2,j2) assigned to h, one must precede the other
# We use the constraint: if assign[h][i1][j1] == 1 and assign[h][i2][j2] == 1, then either
# start_time[i1][j1] + duration[i1][j1] <= start_time[i2][j2] OR start_time[i2][j2] + duration[i2][j2] <= start_time[i1][j1]
# We use big-M with order variables

# Big-M value: upper bound on time (sum of all durations)
M = sum(sum(d) for d in duration) * 2

for h_idx, h in enumerate(hubs):
    for i1 in range(num_routes):
        for j1 in range(num_stages_per_route):
            for i2 in range(num_routes):
                for j2 in range(num_stages_per_route):
                    if i1 == i2 and j1 == j2:
                        continue
                    # Constraint to enforce precedence if both are assigned to hub h
                    # If assign[h][i1][j1] == 1 and assign[h][i2][j2] == 1, then:
                    # start_time[i1][j1] + duration[i1][j1] <= start_time[i2][j2] + M*(1 - order[h][i1][j1][i2][j2])
                    # start_time[i2][j2] + duration[i2][j2] <= start_time[i1][j1] + M*order[h][i1][j1][i2][j2]
                    # Also, we need to link assign and order: if both are assigned, then exactly one order variable is 1
                    model += start_time[i1, j1] + duration[i1][j1] <= start_time[i2, j2] + M * (1 - order[h_idx][i1][j1][i2][j2]), f"R2_precedence_1_{h_idx}_{i1}_{j1}_{i2}_{j2}"
                    model += start_time[i2, j2] + duration[i2][j2] <= start_time[i1, j1] + M * order[h_idx][i1][j1][i2][j2], f"R2_precedence_2_{h_idx}_{i1}_{j1}_{i2}_{j2}"
                    # Ensure that if both are assigned to hub h, then exactly one of the order variables is 1
                    # But note: we have only one order variable per pair (i1,j1,i2,j2) and we don't have the reverse (i2,j2,i1,j1) as a separate variable
                    # So we need to ensure that for each unordered pair, exactly one of the two possible order variables is 1
                    # However, we only defined order[h][i1][j1][i2][j2] for all pairs, including both directions? 
                    # Actually, we defined for every ordered pair (i1,j1,i2,j2) with (i1,j1) != (i2,j2). 
                    # We need to enforce: assign[h][i1][j1] + assign[h][i2][j2] <= 1 + order[h_idx][i1][j1][i2][j2] + order[h_idx][i2][j2][i1][j1]
                    # But we didn't define order[h][i2][j2][i1][j1] as a separate variable? Actually we did, because we looped over all i1,j1,i2,j2.
                    # So we have both order[h][i1][j1][i2][j2] and order[h][i2][j2][i1][j1]. We need to enforce that they are complementary.
                    # However, we have a problem: we have defined both, but we need to ensure that for each pair, exactly one is 1 if both are assigned.
                    # We add:
                    model += assign[h_idx][i1][j1] + assign[h_idx][i2][j2] <= 1 + order[h_idx][i1][j1][i2][j2] + order[h_idx][i2][j2][i1][j1], f"R2_order_link_{h_idx}_{i1}_{j1}_{i2}_{j2}"
                    # But note: we have defined both order variables, so we need to also enforce that they cannot both be 1
                    model += order[h_idx][i1][j1][i2][j2] + order[h_idx][i2][j2][i1][j1] <= 1, f"R2_order_mutual_{h_idx}_{i1}_{j1}_{i2}_{j2}"

# R3: The sequence of hubs for each route must be strictly followed as given.
# This is enforced by the assign variable: each stage j of route i must be assigned to the hub specified in hub_sequence[i][j]
for i in range(num_routes):
    for j in range(num_stages_per_route):
        required_hub = hub_sequence[i][j]
        required_hub_idx = hubs.index(required_hub)
        # Only one hub can be assigned
        model += pulp.lpSum([assign[h_idx][i][j] for h_idx in range(len(hubs))]) == 1, f"R3_assignment_{i}_{j}"
        # And it must be the required hub
        for h_idx in range(len(hubs)):
            if h_idx != required_hub_idx:
                model += assign[h_idx][i][j] == 0, f"R3_required_hub_{i}_{j}_{hubs[h_idx]}"

# R4: The start time of a stage must be non-negative.
# This is already enforced by the lowBound=0 in variable definition, but we write it as constraint for clarity
for i in range(num_routes):
    for j in range(num_stages_per_route):
        model += start_time[i, j] >= 0, f"R4_nonnegativity_{i}_{j}"

# R5: The completion time of each route must equal the end time of its final stage.
for i in range(num_routes):
    last_stage = num_stages_per_route - 1
    model += completion_time[i] == start_time[i, last_stage] + duration[i][last_stage], f"R5_completion_{i}"

# R6: The total completion time is the maximum of all route completion times.
for i in range(num_routes):
    model += makespan >= completion_time[i], f"R6_makespan_{i}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution (optional, for debugging)
if pulp.LpStatus[model.status] == "Optimal":
    print("Optimal solution found:")
    for i in range(num_routes):
        print(f"Route {i+1}:")
        for j in range(num_stages_per_route):
            hub_idx = None
            for h_idx in range(len(hubs)):
                if assign[h_idx][i][j].value() > 0.5:
                    hub_idx = h_idx
                    break
            hub_name = hubs[hub_idx] if hub_idx is not None else "unknown"
            print(f"  Stage {j+1}: Hub {hub_name}, start={start_time[i,j].value():.2f}, duration={duration[i][j]}, end={start_time[i,j].value() + duration[i][j]:.2f}")
        print(f"  Completion time: {completion_time[i].value():.2f}")
    print(f"Total completion time (makespan): {makespan.value():.2f}")
else:
    print("No optimal solution found.")

