    ["H1", "H3", "H5", "H6", "H2", "H9", "H4", "H10", "H7", "H8"]
]

# Create the model
model = pulp.LpProblem("Logistics_Scheduling", pulp.LpMinimize)

# Decision variables
# start_time[r][i]: start time of i-th task in route r
start_time = {}
for r in range(num_routes):
    start_time[r] = {}
    for i in range(num_tasks_per_route):
        start_time[r][i] = pulp.LpVariable(f"start_time_{r}_{i}", lowBound=0)

# finish_time[r][i]: finish time of i-th task in route r
finish_time = {}
for r in range(num_routes):
    finish_time[r] = {}
    for i in range(num_tasks_per_route):
        finish_time[r][i] = pulp.LpVariable(f"finish_time_{r}_{i}", lowBound=0)

# x[r1][i][r2][j]: binary variable indicating whether task i in route r1 precedes task j in route r2 at the same hub
x = {}
for r1 in range(num_routes):
    for i in range(num_tasks_per_route):
        for r2 in range(num_routes):
            for j in range(num_tasks_per_route):
                if r1 == r2 and i == j:
                    continue  # Skip self-comparison
                x[r1][i][r2][j] = pulp.LpVariable(f"x_{r1}_{i}_{r2}_{j}", cat='Binary')

# hub_assignment[r][i]: the hub ID (as index) where the i-th task in route r is performed
hub_assignment = {}
for r in range(num_routes):
    hub_assignment[r] = {}
    for i in range(num_tasks_per_route):
        hub_name = hub_sequence[r][i]
        hub_index = hubs.index(hub_name)
        hub_assignment[r][i] = hub_index

# handling_time[r][i]: handling time for the i-th task in route r
handling_time = {}
for r in range(num_routes):
    handling_time[r] = {}
    for i in range(num_tasks_per_route):
        handling_time[r][i] = hub_handling_times[r][i]

# Constraints

# R1: For each route, the handling tasks must follow the specified sequence of hubs.
# This is enforced by the hub_sequence parameter and hub_assignment, so no additional constraint needed beyond data setup.

# R2: Each handling task at a hub must start only after the previous task in the same route is completed.
for r in range(num_routes):
    for i in range(1, num_tasks_per_route):
        model += start_time[r][i] >= finish_time[r][i-1], f"R2_sequence_{r}_{i}"

# R3: Each hub can process only one task at a time.
# R5: The start time of a task at a hub must be after the completion time of any previous task at that same hub.
# We combine R3 and R5: for any two tasks at the same hub, one must finish before the other starts.
# We use the binary variable x[r1][i][r2][j] to model precedence.
for h in range(len(hubs)):
    # Find all tasks assigned to hub h
    tasks_at_hub = []
    for r in range(num_routes):
        for i in range(num_tasks_per_route):
            if hub_assignment[r][i] == h:
                tasks_at_hub.append((r, i))

    # For every pair of distinct tasks at hub h
    for idx1, (r1, i1) in enumerate(tasks_at_hub):
        for idx2, (r2, i2) in enumerate(tasks_at_hub):
            if idx1 >= idx2:
                continue  # Avoid duplicate and self-pairs

            # Ensure that either task (r1,i1) finishes before (r2,i2) starts, or vice versa
            # We use big-M formulation with binary variable x[r1][i1][r2][i2]
            # If x[r1][i1][r2][i2] = 1, then (r1,i1) finishes before (r2,i2) starts
            # If x[r1][i1][r2][i2] = 0, then (r2,i2) finishes before (r1,i1) starts

            # Constraint: finish_time[r1][i1] <= start_time[r2][i2] + M * (1 - x[r1][i1][r2][i2])
            M = 1000  # Large enough upper bound on makespan (sum of all handling times is at most 10*10*10=1000)
            model += finish_time[r1][i1] <= start_time[r2][i2] + M * (1 - x[r1][i1][r2][i2]), f"R3_R5_precedence_{h}_{r1}_{i1}_{r2}_{i2}"

            # Constraint: finish_time[r2][i2] <= start_time[r1][i1] + M * x[r1][i1][r2][i2]
            model += finish_time[r2][i2] <= start_time[r1][i1] + M * x[r1][i1][r2][i2], f"R3_R5_precedence_{h}_{r2}_{i2}_{r1}_{i1}"

# R4: No task can be interrupted once it starts.
# This is naturally enforced by the continuous processing assumption and the fact that we model each task as a single continuous interval.
# We don't need additional constraints because we are not allowing preemption.

# R6: The makespan is determined by the maximum finish time across all tasks in all routes.
# Define a variable for makespan
makespan = pulp.LpVariable("makespan", lowBound=0)
model += makespan >= finish_time[r][i] for r in range(num_routes) for i in range(num_tasks_per_route)
# But we need to write each constraint individually because we can't use generator in += directly
for r in range(num_routes):
    for i in range(num_tasks_per_route):
        model += makespan >= finish_time[r][i], f"R6_makespan_{r}_{i}"

# Objective: Minimize the makespan
model += makespan, "Minimize_makespan"

# Link finish_time to start_time and handling_time
for r in range(num_routes):
    for i in range(num_tasks_per_route):
        model += finish_time[r][i] == start_time[r][i] + handling_time[r][i], f"R2_finish_time_{r}_{i}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

